	[ 'eans' => [ '8010072255811' ], 'html' => '<p>Enkelt eller dobbelt espresso efter italiensk forbillede. Smegs maskine har et tredobbelt termoblok-system, så den hurtigt er klar til at brygge, og den hvide farve passer til det klassiske Smeg-design.</p><ul><li>Enkelt- og dobbelt espresso</li><li>Tredobbelt termoblok</li><li>Farve: hvid</li></ul>' ],
